          "stageDirection": "Rodolfo e Mimì, in dolce colloquio, si avviano verso il fondo della scena e si perdono nella folla. Ad una bottega del fondo un venditore monta su di una seggiola, con grandi gesti offre in vendita delle maglierie, dei berretti da notte, ecc. Un gruppo di ragazzi accorre intorno alla bottega e scoppia in allegre risate.",
          "stageDirectionTranslation": "Rodolfo and Mimì, in sweet conversation, move toward the back of the scene and lose themselves in the crowd. At a shop in the background a vendor climbs on a chair, with grand gestures offering knitwear, nightcaps, etc. A group of boys gathers around the shop and bursts into cheerful laughter."
