          "stageDirection": "Bambine e ragazzi, attorniato il carretto di Parpignol, gesticolano con gran vivacità; un gruppo di mamme accorre in cerca dei ragazzi e, trovandoli intorno a Parpignol, si mettono a sgridarli; l'una prende il figliolo per una mano, un'altra vuole condur via la propria bambina, chi minaccia, chi sgrida, ma inutilmente, ché bambine e ragazzi non vogliono andarsene.",
          "stageDirectionTranslation": "Girls and boys, surrounding Parpignol's cart, gesticulate with great liveliness; a group of mothers rushes up looking for the children and, finding them around Parpignol, begins scolding them; one takes her son by the hand, another wants to lead her girl away, some threaten, some scold, but in vain, for boys and girls do not want to leave."
