          "stageDirection": "La ritirata Militare entra da sinistra, la precede un gigantesco Tamburo Maggiore, che maneggia con destrezza e solennità la sua Canna di Comando, indicando la via da percorrere.; La Ritirata attraversa la scena, dirigendosi verso il fondo a destra. Musetta non potendo camminare perché ha un solo piede calzato, è alzata a braccia da Marcello e Colline che rompono le fila degli astanti, per seguire la Ritirata; la folla vedendo Musetta portata trionfalmente, ne prende pretesto per farle clamorose ovazioni. Marcello e Colline con Musetta si mettono in coda alla Ritirata, li seguono Rodolfo e Mimì a braccetto e Schaunard col suo corno imboccato, poi studenti e sartine saltellando allegramente, poi ragazzi, borghesi, donne che prendono il passo di marcia. Tutta questa folla si allontana dal fondo seguendo la Ritirata militare.",
          "stageDirectionTranslation": "The military tattoo enters from the left, preceded by a gigantic Drum Major, who wields with skill and solemnity his Staff of Command, indicating the route to follow; The tattoo crosses the stage, heading toward the background right. Musetta, unable to walk having only one shoe on, is lifted onto the arms of Marcello and Colline, who break through the ranks of onlookers to follow the tattoo; the crowd, seeing Musetta carried triumphantly, takes occasion to give her clamorous ovations. Marcello and Colline with Musetta take their place at the tail of the tattoo, followed by Rodolfo and Mimì arm in arm, and Schaunard blowing his horn, then students and workgirls skipping merrily, then boys, citizens, and women falling into marching step. All this crowd moves away into the background following the military tattoo.",
          "pieceTitle": "La ritirata!"
