          "stageDirection": "Grido della folla, dall'interno Intanto Alcindoro con un paio di scarpe bene incartocciate ritorna verso il Caffè Momus cercando di Musetta; il cameriere, che è presso al tavolo, prende il conto lasciato da questa e cerimoniosamente lo presenta ad Alcindoro, il quale vedendo la somma, non trovando più alcuno, cade su di una sedia, stupefatto, allibito.",
